import type {Diagram} from '../../shared/diagram.ts';
export const cicd:Diagram={version:1,type:'flow',title:'CI/CD with a release gate',caption:'Tests run together; release waits for both checks.',nodes:[{id:'change',label:'Code change',kind:'step'},{id:'build',label:'Build',kind:'step'},{id:'unit',label:'Unit tests',kind:'step'},{id:'security',label:'Security check',kind:'step'},{id:'gate',label:'Both checks pass?',kind:'decision'},{id:'release',label:'Release',kind:'step'},{id:'fix',label:'Return to author',kind:'step'}],edges:[{id:'a',from:'change',to:'build'},{id:'b',from:'build',to:'unit'},{id:'c',from:'build',to:'security'},{id:'d',from:'unit',to:'gate'},{id:'e',from:'security',to:'gate'},{id:'f',from:'gate',to:'release',label:'Yes'},{id:'g',from:'gate',to:'fix',label:'No'}],focus:['change','build','unit','security','gate','release']};
export const rag:Diagram={version:1,type:'layers',title:'Retrieval before generation',caption:'The answer uses retrieved passages, not the whole collection.',nodes:[{id:'docs',label:'Documents'},{id:'chunks',label:'Split into passages'},{id:'index',label:'Embedding index'},{id:'question',label:'Question'},{id:'retrieve',label:'Retrieve relevant passages'},{id:'generate',label:'Generate grounded answer'},{id:'answer',label:'Answer with references'}],edges:[{id:'a',from:'docs',to:'chunks'},{id:'b',from:'chunks',to:'index'},{id:'c',from:'question',to:'retrieve'},{id:'d',from:'index',to:'retrieve',label:'Similar passages'},{id:'e',from:'retrieve',to:'generate'},{id:'f',from:'question',to:'generate',label:'Original question'},{id:'g',from:'generate',to:'answer'}],groups:[{id:'preparation',label:'Preparation',nodeIds:['docs','chunks','index']}],focus:['docs','chunks','index','question','retrieve','generate','answer']};
export const lifecycle:Diagram={version:1,type:'sequence',title:'A request with an expired session',caption:'Refresh happens once before the original request continues.',nodes:[{id:'user',label:'Browser',kind:'actor'},{id:'api',label:'App server',kind:'actor'},{id:'auth',label:'Identity service',kind:'actor'}],edges:[{id:'send',from:'user',to:'api',label:'Send request'},{id:'expired',from:'api',to:'user',label:'Session expired'},{id:'refresh',from:'user',to:'auth',label:'Refresh session'},{id:'ready',from:'auth',to:'user',label:'New session'},{id:'retry',from:'user',to:'api',label:'Repeat original request'},{id:'ok',from:'api',to:'user',label:'Successful response'}],focus:['send','expired','refresh','ready','retry','ok']};
